    @staticmethod
    def _best_chat_instance(instances: Any, expected: list[str]) -> dict[str, Any]:
        candidates = [dict(item) for item in instances or [] if isinstance(item, Mapping)]
        if not candidates:
            return {}
        return max(
            candidates,
            key=lambda item: (
                sum(
                    normalize_message_text(target)
                    in {normalize_message_text(text) for text in DeltaChatOrionLaunchHandoffEvaluator._self_texts(item)}
                    for target in expected
                ),
                int(item.get("chat_id") or 0),
            ),
        )

    @staticmethod
    def _self_texts(instance: Mapping[str, Any] | None) -> list[str]:
        return [
            str(item.get("text") or "")
            for item in (instance or {}).get("messages", [])
            if item.get("from_self") and str(item.get("text") or "").strip()
        ]

    @staticmethod
    def _is_ordered_subsequence(expected: list[str], observed: list[str]) -> bool:
        iterator = iter(normalize_message_text(item) for item in observed)
        return all(
            any(candidate == normalize_message_text(target) for candidate in iterator)
            for target in expected
        )

    @staticmethod
    def _normalize_sequences(raw: Any) -> dict[str, list[str]]:
        return {
            str(chat).strip(): [str(item) for item in values if str(item).strip()]
            for chat, values in dict(raw or {}).items()
            if str(chat).strip() and isinstance(values, list)
        }

    @staticmethod
    def _normalize_source_copies(raw: Any) -> list[dict[str, str]]:
        normalized: list[dict[str, str]] = []
        for index, item in enumerate(raw or []):
            if not isinstance(item, Mapping):
                continue
            candidate = {
                "check_id": str(item.get("check_id") or f"source_copy_{index + 1}").strip(),
                "source_chat": str(item.get("source_chat") or "").strip(),
                "search_token": str(item.get("search_token") or "").strip(),
                "target_chat": str(item.get("target_chat") or "").strip(),
                "suffix": str(item.get("suffix") or ""),
            }
            if all(candidate[key] for key in ("check_id", "source_chat", "search_token", "target_chat", "suffix")):
                normalized.append(candidate)
        return normalized

    @staticmethod
    def _normalize_required_attachments(raw: Any) -> list[dict[str, str]]:
        normalized: list[dict[str, str]] = []
        for index, item in enumerate(raw or []):
            if not isinstance(item, Mapping):
                continue
            candidate = {
                "check_id": str(
                    item.get("check_id") or f"required_attachment_{index + 1}"
                ).strip(),
                "chat_name": str(item.get("chat_name") or "").strip(),
                "filename": str(item.get("filename") or "").strip(),
                "mime_type": str(item.get("mime_type") or "").strip(),
            }
            if all(candidate[key] for key in ("check_id", "chat_name", "filename")):
                normalized.append(candidate)
        return normalized

